// coupled-subsystem simulation sketch for: CASCADE Model
const subs = [
  {name:'power', x:0.736, k:0.141},
  {name:'thermal', x:0.883, k:0.174},
  {name:'structural', x:0.71, k:0.12},
  {name:'control', x:0.387, k:0.15},
  {name:'comms', x:0.395, k:0.17},
];
for (let t = 0; t < 60; t++) {
  for (const s of subs) { s.x += s.k * (1 - s.x) - 0.015 * s.x; }
}
const fin = subs.map(s => +s.x.toFixed(4));
console.log(JSON.stringify({subsystems: subs.length, steps: 60,
  finalState: fin, converged: fin.every(v => v > 0 && v < 1.5),
  topic: 'CASCADE Model'}));

